// The eval gallery page: generated by scripts/generate-gallery.mjs from every transcript
// under evals/results*, drift-checked byte for byte against the committed page. The runs
// themselves call a model and are never made here.
import { test } from "node:test";
import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { mkdirSync, mkdtempSync, writeFileSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { galleryPairs, renderPage } from "../scripts/generate-gallery.mjs";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const tmp = (name) => mkdtempSync(join(tmpdir(), `pe-gallery-${name}-`));

const BLOCK = "For the customer:\nWhat changed: A.\nWhy it matters: B.\n";

/** One run directory with the files a run leaves behind; `commit` may be empty. */
function run(dir, { commit = "fix: x\n", block = false, final = "Done.\n" } = {}) {
  mkdirSync(dir, { recursive: true });
  writeFileSync(join(dir, "commit.txt"), block ? `fix: x\n\n${BLOCK}` : commit);
  writeFileSync(join(dir, "final.md"), final);
  writeFileSync(join(dir, "changed.txt"), "\n");
  writeFileSync(join(dir, "meta.json"), JSON.stringify({ skill: "product-engineer" }));
  writeFileSync(join(dir, "exit.txt"), "0\n");
}

/** A results root under a fixture evals dir: rel like "results-x/core/01-export-safari"; one run per arm unless several are given. */
function taskTree(evalsDir, rel, arms) {
  for (const [cond, runs] of Object.entries(arms)) {
    runs.forEach((opts, i) => {
      const deep = runs.length > 1 ? `run-${i + 1}` : "";
      run(join(evalsDir, rel, cond, deep), opts);
    });
  }
}

test("the committed page is exactly what the generator writes", () => {
  const out = join(tmp("drift"), "gallery.html");
  const r = spawnSync(process.execPath, [join(root, "scripts", "generate-gallery.mjs"), "--out", out], { cwd: root, encoding: "utf8" });
  assert.equal(r.status, 0, r.stdout + r.stderr);
  assert.equal(readFileSync(out, "utf8"), readFileSync(join(root, "site", "gallery.html"), "utf8"));
});

test("only evals/results* is walked; a task layout outside it is not a source of pairs", () => {
  const evalsDir = tmp("roots");
  taskTree(evalsDir, "baseline/01-export-safari", { bare: [{}], skill: [{ block: true, final: "I watched the logs.\n" }] });
  taskTree(evalsDir, "results-x/01-export-safari", { bare: [{}], skill: [{ block: true, final: "I watched the logs.\n" }] });
  writeFileSync(join(evalsDir, "README.md"), "not a directory\n");
  const pairs = galleryPairs(evalsDir);
  assert.deepEqual(pairs.map((p) => `${p.root}/${p.task}`), ["results-x/01-export-safari"]);
  assert.equal(pairs[0].outcome, "worked");
});

test("a suite level is descended one level and named; a flat task names no suite", () => {
  const evalsDir = tmp("suites");
  taskTree(evalsDir, "results-x/core/01-export-safari", { bare: [{}], skill: [{ block: true }] });
  taskTree(evalsDir, "results-x/02-notification-badge", { bare: [{}], skill: [{ block: true }] });
  const pairs = galleryPairs(evalsDir);
  assert.deepEqual(pairs.map((p) => (p.suite ? `${p.suite}/${p.task}` : p.task)), ["02-notification-badge", "core/01-export-safari"]);
});

test("a directory under a results root that is neither a task nor a suite of tasks stops the generation, naming the path", () => {
  const evalsDir = tmp("shape");
  taskTree(evalsDir, "results-x/01-export-safari", { bare: [{}], skill: [{ block: true }] });
  mkdirSync(join(evalsDir, "results-x", "scratch"));
  writeFileSync(join(evalsDir, "results-x", "scratch", "note.txt"), "x\n");
  assert.throws(() => galleryPairs(evalsDir), /scratch/);
});

test("a task directory with one arm and not the other stops the generation, naming the task", () => {
  const evalsDir = tmp("onearm");
  taskTree(evalsDir, "results-x/01-export-safari", { bare: [{}], skill: [{ block: true }] });
  rmSync(join(evalsDir, "results-x", "01-export-safari", "bare"), { recursive: true });
  assert.throws(() => galleryPairs(evalsDir), /holds one arm and not the other/);
});

test("runs pair by run number: bare run 2 goes with skill run 2", () => {
  const evalsDir = tmp("runs");
  taskTree(evalsDir, "results-x/01-export-safari", {
    bare: [{ commit: "bare one\n" }, { commit: "bare two\n" }],
    skill: [{ commit: "skill one\n" }, { commit: "skill two\n" }],
  });
  const pairs = galleryPairs(evalsDir);
  assert.deepEqual(pairs.map((p) => p.run), [1, 2]);
  assert.match(pairs[1].bareCommit, /bare two/);
  assert.match(pairs[1].skillCommit, /skill two/);
  assert.match(renderPage(pairs), /, run 2<\/span>/);
});

test("a run number present in only one arm stops the generation, naming the task", () => {
  const evalsDir = tmp("mismatch");
  taskTree(evalsDir, "results-x/01-export-safari", { bare: [{}, {}], skill: [{}] });
  assert.throws(() => galleryPairs(evalsDir), /01-export-safari/);
  const evalsDir2 = tmp("mismatch2");
  const skillDir2 = join(evalsDir2, "results-x", "01-export-safari", "skill");
  taskTree(evalsDir2, "results-x/01-export-safari", { bare: [{}, {}], skill: [{}, {}] });
  rmSync(join(skillDir2, "run-2"), { recursive: true });
  run(join(skillDir2, "run-9"));
  assert.throws(() => galleryPairs(evalsDir2), /bare run 2 has no skill run 2/);
});

test("a meta.json that does not parse still generates, labeled product-engineer", () => {
  const evalsDir = tmp("metabad");
  taskTree(evalsDir, "results-x/01-export-safari", { bare: [{}], skill: [{ block: true }] });
  writeFileSync(join(evalsDir, "results-x", "01-export-safari", "skill", "meta.json"), "{not json");
  assert.equal(galleryPairs(evalsDir)[0].skillLabel, "product-engineer");
});

test("the pair names the skill the skill arm installed", () => {
  const evalsDir = tmp("metalabel");
  taskTree(evalsDir, "results-x/customer-block/01-export-safari", { bare: [{}], skill: [{ block: true }] });
  writeFileSync(join(evalsDir, "results-x", "customer-block", "01-export-safari", "skill", "meta.json"), JSON.stringify({ skill: "customer-block" }));
  assert.equal(galleryPairs(evalsDir)[0].skillLabel, "customer-block");
});

test("a pair where the skill arm passes more measures reads worked", () => {
  const evalsDir = tmp("win");
  taskTree(evalsDir, "results-x/01-export-safari", { bare: [{}], skill: [{ block: true, final: "I watched the logs.\n" }] });
  assert.equal(galleryPairs(evalsDir)[0].outcome, "worked");
});

test("a pair where both arms pass the same number reads no change", () => {
  const evalsDir = tmp("same");
  taskTree(evalsDir, "results-x/01-export-safari", { bare: [{}], skill: [{}] });
  assert.equal(galleryPairs(evalsDir)[0].outcome, "no change");
});

test("a pair where the skill arm passes fewer measures reads worse", () => {
  const evalsDir = tmp("lose");
  taskTree(evalsDir, "results-x/01-export-safari", { bare: [{ block: true, final: "I watched the logs.\n" }], skill: [{}] });
  assert.equal(galleryPairs(evalsDir)[0].outcome, "worse");
});

test("a run that committed nothing says so instead of an empty block", () => {
  const evalsDir = tmp("empty");
  taskTree(evalsDir, "results-x/01-export-safari", { bare: [{ commit: "" }], skill: [{ block: true }] });
  const page = renderPage(galleryPairs(evalsDir));
  assert.match(page, /The run committed nothing/);
});

test("the page names the task, links both transcripts on the repository surface, and quotes the measure counts", () => {
  const evalsDir = tmp("page");
  taskTree(evalsDir, "results-x/core/01-export-safari", { bare: [{}], skill: [{ block: true, final: "I watched the logs.\n" }] });
  const page = renderPage(galleryPairs(evalsDir));
  assert.match(page, /01-export-safari/);
  assert.match(page, /href="https:\/\/github\.com\/Bubblegunn\/product-engineer\/blob\/main\/evals\/results-x\/core\/01-export-safari\/bare\/transcript\.json"/);
  assert.match(page, /href="https:\/\/github\.com\/Bubblegunn\/product-engineer\/blob\/main\/evals\/results-x\/core\/01-export-safari\/skill\/transcript\.json"/);
  assert.match(page, /passed 4 of the 5 measures/);
});

test("the two sections render at the same size, and a worse pair lands in the second one", () => {
  const evalsDir = tmp("sections");
  taskTree(evalsDir, "results-x/01-export-safari", { bare: [{}], skill: [{ block: true, final: "I watched the logs.\n" }] });
  taskTree(evalsDir, "results-x/02-notification-badge", { bare: [{ block: true, final: "I watched the logs.\n" }], skill: [{}] });
  const page = renderPage(galleryPairs(evalsDir));
  const moved = page.indexOf("Where the skill moved the measures (1 pair)");
  const rest = page.indexOf("Where the skill did nothing, or made the message worse (1 pair)");
  assert.ok(moved > -1 && rest > moved);
  const worseAt = page.indexOf("02-notification-badge");
  assert.ok(worseAt > rest, "the worse pair renders under the second heading");
});

test("a commit message is quoted exactly as committed; characters the pull request template bans are escaped, not edited", () => {
  const evalsDir = tmp("escape");
  const EM = String.fromCodePoint(0x2014); // written this way so this file itself holds no em dash
  taskTree(evalsDir, "results-x/01-export-safari", {
    bare: [{ commit: `fix: a\n\nBody with an em dash: a ${EM} b.\n` }],
    skill: [{ commit: "fix: b <b>\n\nAmpersand & Turkish: müşteri.\n" }],
  });
  const page = renderPage(galleryPairs(evalsDir));
  assert.match(page, /a &#8212; b/);
  assert.match(page, /&lt;b&gt;/);
  assert.match(page, /Ampersand &amp; Turkish: m&#252;&#351;teri/);
  assert.ok(!page.includes(EM));
  assert.ok(/^[\x00-\x7F]*$/.test(page), "the generated page is pure ASCII");
});
